/**
 * src/components/VerdictCard.tsx — Double-bezel verdict card with a
 * cascade badge and a GSAP ScrollTrigger word-scrub on the reasoning.
 * All Tailwind classes are static strings per verdict — runtime-constructed
 * class names don't get generated by Tailwind's JIT.
 */

import { useRef, useMemo } from "react";
import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { ShieldCheck, ShieldX, ShieldAlert, ShieldQuestion } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import type { Verification, VerdictType } from "../types";

gsap.registerPlugin(useGSAP, ScrollTrigger);

interface VerdictCardProps {
  verification: Verification;
}

const VERDICT_STYLES: Record<
  VerdictType,
  {
    label: string;
    icon: typeof ShieldCheck;
    badge: string;
    bar: string;
    glow: string;
  }
> = {
  True: {
    label: "Verified true",
    icon: ShieldCheck,
    badge: "bg-emerald-400 text-neutral-950",
    bar: "bg-emerald-400 shadow-[0_0_20px_rgba(52,211,153,0.4)]",
    glow: "bg-emerald-400/25 blur-2xl",
  },
  False: {
    label: "Verified false",
    icon: ShieldX,
    badge: "bg-rose-400 text-neutral-950",
    bar: "bg-rose-400 shadow-[0_0_20px_rgba(251,113,133,0.4)]",
    glow: "bg-rose-400/25 blur-2xl",
  },
  Misleading: {
    label: "Misleading",
    icon: ShieldAlert,
    badge: "bg-amber-400 text-neutral-950",
    bar: "bg-amber-400 shadow-[0_0_20px_rgba(251,191,36,0.4)]",
    glow: "bg-amber-400/25 blur-2xl",
  },
  Unverified: {
    label: "Unverified",
    icon: ShieldQuestion,
    badge: "bg-neutral-300 text-neutral-950",
    bar: "bg-neutral-400 shadow-[0_0_20px_rgba(161,161,170,0.3)]",
    glow: "bg-neutral-400/20 blur-2xl",
  },
};

export function VerdictCard({ verification }: VerdictCardProps) {
  const cardRef = useRef<HTMLDivElement>(null);
  const style = VERDICT_STYLES[(verification.verdict as VerdictType) || "Unverified"] ?? VERDICT_STYLES.Unverified;
  const Icon = style.icon;

  // Split reasoning into word spans once for the scrub reveal
  const words = useMemo(
    () => (verification.reasoning || "").split(/(\s+)/).filter((w) => w.length > 0),
    [verification.reasoning]
  );

  // Scrubbing text reveal — word opacity 0.12 -> 1 sequentially on scroll
  useGSAP(
    () => {
      const targets = gsap.utils.toArray<HTMLElement>("[data-word]", cardRef.current);
      if (targets.length === 0) return;
      const tween = gsap.fromTo(
        targets,
        { opacity: 0.12 },
        {
          opacity: 1,
          stagger: 0.02,
          ease: "none",
          scrollTrigger: {
            trigger: cardRef.current,
            start: "top 78%",
            end: "top 22%",
            scrub: 0.6,
          },
        }
      );
      return () => {
        tween.scrollTrigger?.kill();
        tween.kill();
      };
    },
    { scope: cardRef, dependencies: [verification.id, words.length] }
  );

  return (
    <div ref={cardRef} className="relative z-10">
      {/* Cascade — shadcn Badge floats above the shell, straddling its edge */}
      <Badge
        data-reveal-badge
        className={`absolute -top-3 left-6 z-20 flex items-center gap-2 px-3.5 py-2 rounded-full text-xs font-semibold tracking-tight shadow-[0_8px_32px_-8px_rgba(0,0,0,0.6)] border-0 ${style.badge}`}
      >
        <Icon size={13} strokeWidth={1.5} />
        {style.label}
      </Badge>
      {/* Ambient verdict glow behind the shell */}
      <div className={`absolute -inset-4 -z-10 rounded-[2.5rem] ${style.glow} opacity-40`} aria-hidden="true" />

      {/* Outer shell — machined tray */}
      <div className="rounded-[2rem] p-1.5 bg-white/[0.04] ring-1 ring-white/10 shadow-[inset_0_1px_1px_rgba(255,255,255,0.08),0_40px_80px_-40px_rgba(0,0,0,0.9)]">
        {/* Inner core — glass plate */}
        <div className="rounded-[calc(2rem-0.375rem)] bg-[#0a0a0b] p-6 md:p-8">
          {/* Confidence — oversized mono tabular figures */}
          <div className="mb-8">
            <div className="flex items-end justify-between mb-4">
              <span className="text-[10px] font-medium text-neutral-500 tracking-[0.2em] uppercase mb-2">Confidence</span>
              <span className="font-mono font-medium text-5xl md:text-6xl text-neutral-100 tabular-nums leading-none tracking-tight">
                {verification.confidence}
                <span className="text-neutral-600 text-2xl">%</span>
              </span>
            </div>
            <div className="h-1.5 w-full rounded-full bg-white/[0.07] overflow-hidden">
              <div
                className={`h-full rounded-full ${style.bar}`}
                style={{
                  width: `${verification.confidence}%`,
                  transition: "width 1.2s cubic-bezier(0.32, 0.72, 0, 1)",
                }}
              />
            </div>
          </div>

          {/* Reasoning — scrubbed word-by-word on scroll */}
          <div>
            <h3 className="text-[10px] font-medium text-neutral-500 tracking-[0.2em] uppercase mb-3">Reasoning</h3>
            <p className="text-[15px] text-neutral-300 leading-relaxed whitespace-pre-wrap text-pretty max-w-[62ch]">
              {words.map((w, i) => (
                <span key={i} data-word className={w.trim() === "" ? "" : "inline-block"}>
                  {w}
                  {w.endsWith("\n") ? "" : " "}
                </span>
              ))}
            </p>
          </div>

          {/* Sources count */}
          <div className="mt-8 pt-5 border-t border-white/[0.06] flex items-center gap-2 text-xs text-neutral-500">
            <span className="text-neutral-400">{verification.sources?.length || 0} sources reviewed</span>
            <span className="font-mono tabular-nums text-neutral-600">·</span>
            <span className="font-mono tabular-nums">trace below</span>
          </div>
        </div>
      </div>
    </div>
  );
}
